import{_ as t,o as s,c as o,ah as r}from"./chunks/framework.ChH6X6u6.js";const d=JSON.parse('{"title":"Course element marks (higher education)","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/enseignant/notes-superieur.md","filePath":"src/en/guide/enseignant/notes-superieur.md"}'),n={name:"en/guide/enseignant/notes-superieur.md"};function a(i,e,h,m,l,u){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="course-element-marks-higher-education" tabindex="-1">Course element marks (higher education) <a class="header-anchor" href="#course-element-marks-higher-education" aria-label="Permalink to &quot;Course element marks (higher education)&quot;">​</a></h1><p>In a higher education programme, you mark <strong>course elements</strong>, promotion by promotion. The programme head assigns them to you from each promotion&#39;s <strong>Teaching</strong> page.</p><p>Your elements are under <strong>Higher education → Course element marks</strong>. Each line gives the promotion, the unit and the period, with two sheets: <strong>First session</strong> and <strong>Retake</strong>.</p><h2 id="the-first-session" tabindex="-1">The first session <a class="header-anchor" href="#the-first-session" aria-label="Permalink to &quot;The first session&quot;">​</a></h2><p>The sheet lists the students who take the element: the whole promotion for a mandatory unit, only those registered for an elective one.</p><p>For each, enter out of 20:</p><ul><li>the <strong>continuous assessment</strong>;</li><li>the <strong>exam</strong>, or tick <strong>Absent</strong>: an absence at the exam counts as 0.</li></ul><p>The <strong>Element mark</strong> column is worked out as you type, from the share of continuous assessment the programme sets (40% by default). It shows in orange below the pass mark. Click <strong>Save marks</strong>.</p><p>An emptied line erases the student&#39;s marks: it is not a zero.</p><div class="tip custom-block"><p class="custom-block-title">Depending on the programme</p><p>Some programmes mark their elements on continuous assessment alone or on the exam alone: the sheet then shows only the column that counts.</p></div><h2 id="the-retake" tabindex="-1">The retake <a class="header-anchor" href="#the-retake" aria-label="Permalink to &quot;The retake&quot;">​</a></h2><p>The retake sheet only lists the students who sit it: their unit is not validated after the first session (compensation included) and their mark in this element is below the pass mark.</p><p>Enter the <strong>retake exam</strong> mark, or tick <strong>Absent</strong>. It replaces the first session&#39;s exam; the continuous assessment stands. The programme then decides which mark the element keeps: the retake&#39;s, the better of the two, or the retake&#39;s capped.</p><h2 id="a-closed-year" tabindex="-1">A closed year <a class="header-anchor" href="#a-closed-year" aria-label="Permalink to &quot;A closed year&quot;">​</a></h2><p>Once the year is closed, its sheets can still be read but no longer changed.</p>',15)])])}const p=t(n,[["render",a]]);export{d as __pageData,p as default};
